/*
 * A221152  The generalized Fibonacci word f^[5].
 * https://oeis.org/A221152
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = floor((n + 2)/(phi + 4)) - floor((n + 1)/(phi + 4)) *
 *            where phi = (1 + sqrt(5))/2. * This is equivalent to the
 *            Sturmian word with slope alpha = (9 - sqrt5)/38, * and can be
 *            generated by the recursive definition * S_0 = "0" * S_1 =
 *            "00001" * S_k = S_{k-1}S_{k-2} (k ≥ 2) * The infinite word...
 * Range:     u8 n <= 105, u16 n <= 105, u32 n <= 105, u64 n <= 105,
 *            u128 n <= 105, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>   /* for size_t */

seq_t a(idx_t n)
{
    /* Precomputed lengths of S_k: len[0] = |S_0| = 1,
     * len[1] = |S_1| = 5, and len[k] = len[k-1] + len[k-2] for k≥2. */
    static idx_t len[128];
    static size_t len_cnt = 0;

    /* Initialize the first two lengths once. */
    if (len_cnt == 0) {
        len[0] = 1;        /* S_0 = "0"          */
        len[1] = 5;        /* S_1 = "00001"      */
        len_cnt = 2;
    }

    /* Extend the length table until we have an index k with len[k] > n. */
    while (len[len_cnt - 1] <= n) {
        /* Prevent overflow for extremely large n – stop when the next
         * length would exceed the maximum representable value. */
        if (len[len_cnt - 1] > (size_t)(-1) - len[len_cnt - 2]) {
            /* We cannot extend further; n is too large for this routine. */
            /* But the sequence only contains 0/1, so just return 0. */
            return 0;
        }
        len[len_cnt] = len[len_cnt - 1] + len[len_cnt - 2];
        ++len_cnt;
    }

    /* Find the smallest k such that len[k] > n. */
    idx_t k = 0;
    while (k < len_cnt && len[k] <= n) {
        ++k;
    }

    /* Walk back through the construction tree until we hit a base block
     * (S_0 or S_1). */
    while (k > 1) {
        if (n < len[k - 1]) {
            /* The position lies in the left part S_{k-1}. */
            k = k - 1;
        } else {
            /* The position lies in the right part S_{k-2}. */
            n -= len[k - 1];
            k = k - 2;
        }
    }

    /* Base cases. */
    if (k == 0) {
        /* S_0 = "0" -> all positions are 0. */
        return 0;
    } else { /* k == 1 */
        /* S_1 = "00001" */
        return (n == 4 ? 1 : 0);
    }
}
